import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ----------------------------------------------------------------------
# 1️⃣  Custom CUDA kernel for element‑wise addition (matches the example)
# ----------------------------------------------------------------------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

# ----------------------------------------------------------------------
# 2️⃣  Custom CUDA kernel for a naive 2‑D convolution (naive implementation)
# ----------------------------------------------------------------------
conv2d_cpp_source = "torch::Tensor conv2d_cuda(torch::Tensor input, torch::Tensor weight);"

conv2d_kernel = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(const float* input, const float* weight,
                               float* output,
                               int batch_size, int in_channels,
                               int out_channels,
                               int ksize, int stride, int padding, int dilation) {
    // Naive convolution: each thread computes one output element (b, oc, i_out, j_out)
    int b = 0;                     // batch index – only one thread per batch
    int oc = blockIdx.y * blockDim.y + threadIdx.y;
    int i_out = blockIdx.x * blockDim.x + threadIdx.x;

    if (oc < out_channels && i_out < input.size(2)) {   // height
        float sum = 0.0f;
        for (int c = 0; c < in_channels; ++c) {
            for (int ki = -dilation / 2; ki <= ksize / 2 + dilation / 2; ++ki) {
                int kh = ki * ksize + ki;
                float a_val = input[b * in_channels * input.size(2) * input.size(3) +
                                 c * input.size(2) * input.size(3) + i_out * input.size(3)];
                // weight index: (oc, c, (ki % ksize)*ksize + ki)
                int w_idx = oc * in_channels * ksize * ksize + c * ksize * ksize +
                            (ki % ksize) * ksize + ki;
                float w_val = weight[b * out_channels * in_channels * ksize * ksize +
                                   c * out_channels * ksize * ksize + oc * ksize * ksize +
                                   (ki % ksize) * ksize + ki];
                sum += a_val * w_val;
            }
        }
        int out_idx = b * out_channels * input.size(2) * input.size(3) +
                      oc * input.size(2) * input.size(3) + i_out * input.size(3);
        output[b * out_channels * input.size(2) * input.size(3) + oc * input.size(2) * input.size(3) + i_out * input.size(3)] = sum;
    }
}

torch::Tensor conv2d_cuda(torch::Tensor input, torch::Tensor weight) {
    auto size = input.numel();
    float* out_ptr = (float*)malloc(size * sizeof(float));
    if (!out_ptr) return nullptr;

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    conv2d_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), weight.data_ptr<float>(), out_ptr,
                                               input.size(0), input.size(1),
                                               conv2d.out_channels, ksize, stride, padding, dilation);

    float* output = (float*)malloc(input.numel() * sizeof(float));
    if (cudaMemcpy(out_ptr, output, size * sizeof(float))) {
        free(out_ptr);
        free(output);
    }
    return torch::from_blob(output, [size]).contiguous().view(torch::Tensor).to(device=weight.device);
}
"""

