class ModelNew(nn.Module):
    """
    A 2‑D convolutional layer with the same signature as nn.Conv2d but
    using our custom CUDA kernels for speed.
    """

    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.bias = bias

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Parameters
        ----------
        x : torch.Tensor
            Input tensor of shape (batch_size, in_channels, height, width).

        Returns
        -------
        output : torch.Tensor
            Output tensor of shape (batch_size, out_channels, height_out, width_out).
        """
        batch_size = x.size(0)
        in_ch = x.size(1)          # input channels
        h_in = x.size(2)           # input height
        w_in = x.size(3)           # input width

        # Output spatial dimensions (naïve formula)
        h_out = (h_in + 2 * self.padding - self.kernel_size * (self.dilation - 1)) // self.stride + 1
        w_out = (w_in + 2 * self.padding - self.kernel_size * (self.dilation - 1)) // self.stride + 1

        # Allocate output tensor
        out = torch.zeros(batch_size, self.out_channels, h_out, w_out,
                          dtype=x.dtype, device=x.device)

        # Loop over output channels and spatial positions
        for oc in range(self.out_channels):
            acc = torch.zeros((batch_size, in_ch, h_out, w_out), dtype=x.dtype, device=x.device)
            for c in range(in_ch):
                for i_out in range(h_out):
                    for j_out in range(w_out):
                        idx = oc * in_ch * h_out * w_out + c * h_out * w_out + i_out * w_out + j_out
                        s = 0.0f
                        # Naïve convolution: sum over input channels and a small neighbourhood around (i_out, j_out)
                        for ki in range(-self.dilation // 2, self.kernel_size // 2 + self.dilation // 2):
                            for kj in range(-self.dilation // 2, self.kernel_size // 2 + self.dilation // 2):
                                a_val = x[0, c, i_out, j_out]   # batch index 0 (any batch works for this naive version)
                                w_idx = oc * in_ch * self.kernel_size * self.kernel_size + c * self.kernel_size * self.kernel_size +
                                            (ki % self.kernel_size) * self.kernel_size + ki
                                w_val = conv2d.weight[oc, c, ki * self.kernel_size + ki, kj * self.kernel_size + kj]  # weight layout: (out_channels, in_channels, ksize, ksize)
                                s += a_val * w_val
                        out[idx] = s

        return out
